1	package warranty
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件回归保障同一使用编号在并发提交下只产生一次真实扣减：首次成功把使用
11	// 编号与承诺编号、使用数量绑定（当前时刻不属于绑定内容）。此后相同内容的提交
12	// 都取回同一份完整使用记录，不同内容的提交一律 ErrConflict；无论成功返回多少
13	// 次，承诺累计已用数量与备件实物库存都只变化一次，有效占用只减少实际使用的
14	// 数量，可承诺数量保持原值。这些测试只沿用登记、预留、使用与查询的既有公开
15	// 行为。
16	
17	// concurrentUseCall 是一次并发使用提交的入参。
18	type concurrentUseCall struct {
19		usageID  string
20		commitID string
21		quantity int
22		now      time.Time
23	}
24	
25	// concurrentUseResult 是一次并发使用提交的结果。
26	type concurrentUseResult struct {
27		usage Usage
28		err   error
29	}
30	
31	// fanOutConcurrentUse 让全部调用在同一道闸机释放后同时进入 Use，尽量制造交叉；
32	// 返回与调用一一对应的结果，调用方按下标分组核对成功记录与冲突。
33	func fanOutConcurrentUse(s *Store, calls []concurrentUseCall) []concurrentUseResult {
34		results := make([]concurrentUseResult, len(calls))
35		var wg sync.WaitGroup
36		start := make(chan struct{})
37		for i, c := range calls {
38			wg.Add(1)
39			go func(i int, c concurrentUseCall) {
40				defer wg.Done()
41				<-start
42				results[i].usage, results[i].err = s.Use(c.usageID, c.commitID, c.quantity, c.now)
43			}(i, c)
44		}
45		close(start)
46		wg.Wait()
47		return results
48	}
49	
50	// identicalUseCalls 构造 n 个内容完全相同的使用调用；每个调用给不同但都处于
51	// 承诺有效期内的当前时刻，以证明当前时刻不属于绑定内容。
52	func identicalUseCalls(usageID, commitID string, quantity, n int) []concurrentUseCall {
53		calls := make([]concurrentUseCall, n)
54		for i := range calls {
55			calls[i] = concurrentUseCall{
56				usageID:  usageID,
57				commitID: commitID,
58				quantity: quantity,
59				now:      nowOK.Add(time.Duration(i) * time.Hour),
60			}
61		}
62		return calls
63	}
64	
65	// TestConcurrentUseSameIDDeductsOnce 验证多个调用同时提交相同的使用编号、承诺
66	// 编号和数量时全部成功、返回同一份完整使用记录，但承诺已用数量与实物库存只
67	// 变化一次。含“这一次恰好耗尽承诺余量”的边界：其余相同内容提交仍取回首次
68	// 结果，不能被当作新的超量使用拒绝。
69	func TestConcurrentUseSameIDDeductsOnce(t *testing.T) {
70		t.Run("partial use", func(t *testing.T) {
71			s := newStore(t)
72			if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
73				t.Fatalf("reserve: %v", err)
74			}
75			const n = 16
76			results := fanOutConcurrentUse(s, identicalUseCalls("u1", "c1", 2, n))
77	
78			want := Usage{ID: "u1", CommitmentID: "c1", Quantity: 2}
79			for i, r := range results {
80				if r.err != nil || r.usage != want {
81					t.Fatalf("call %d = %+v, err %v; want first record %+v", i, r.usage, r.err, want)
82				}
83			}
84			// 成功返回 n 次，真实扣减只有一次：实物八件、有效占用三件（c1 未用三）。
85			st, _ := s.PartStatus("part1", nowOK)
86			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
87				t.Fatalf("stock = %+v, want phys=8 occupied=3 committable=5", st)
88			}
89			c1, _ := s.Commitment("c1")
90			if c1.Used != 2 || c1.Unused() != 3 {
91				t.Fatalf("c1 = used %d / unused %d, want 2/3", c1.Used, c1.Unused())
92			}
93		})
94	
95		t.Run("exactly exhausts remaining", func(t *testing.T) {
96			s := newStore(t)
97			if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
98				t.Fatalf("reserve: %v", err)
99			}
100			const n = 16
101			results := fanOutConcurrentUse(s, identicalUseCalls("u1", "c1", 5, n))
102	
103			want := Usage{ID: "u1", CommitmentID: "c1", Quantity: 5}
104			for i, r := range results {
105				// 恰好耗尽余量：相同内容的并发提交仍取回首次结果，不按超量使用拒绝。
106				if r.err != nil || r.usage != want {
107					t.Fatalf("call %d = %+v, err %v; want first record %+v", i, r.usage, r.err, want)
108				}
109			}
110			st, _ := s.PartStatus("part1", nowOK)
111			if st.PhysicalRemaining != 5 || st.ActiveOccupied != 0 || st.Committable != 5 {
112				t.Fatalf("stock = %+v, want phys=5 occupied=0 committable=5", st)
113			}
114			c1, _ := s.Commitment("c1")
