180				if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
181					t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
182				}
183				conflict++
184			}
185		}
186		if success != n || conflict != n {
