190		// 结束数量：实物八件、有效占用六件（c1 与 c2 未用之和）、可承诺两件。
191		st, _ := s.PartStatus("part1", nowOK)
192		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 6 || st.Committable != 2 {
193			t.Fatalf("stock = %+v, want phys=8 occupied=6 committable=2 (winner=%s)", st, winner)
194		}
