220	// 数量不同也属于不同内容竞争同一编号：成功记录与最终扣减量必须对应同一份
221	// 提交（两件或四件），胜出组全部返回同一记录，落败组全部 ErrConflict。赛后
222	// 按胜出内容提交取回原记录，按另一份内容提交仍冲突，冲突不覆盖记录、不额外
223	// 扣减。
224	func TestConcurrentUseSameIDDifferentQuantitySingleWinner(t *testing.T) {
225		s := newStore(t)
226		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
227			t.Fatalf("reserve: %v", err)
228		}
229	
230		const n = 12
231		calls := make([]concurrentUseCall, 0, 2*n)
