239	
240		// 胜出数量由承诺实际已用数量判定：只能是两份内容之一，不能是两者叠加。
241		c1c, _ := s.Commitment("c1")
242		var winnerQty, loserQty int
243		switch c1c.Used {
244		case 2:
245			winnerQty, loserQty = 2, 4
246		case 4:
247			winnerQty, loserQty = 4, 2
248		default:
249			t.Fatalf("c1 used = %d, want exactly 2 or 4 (single winning content)", c1c.Used)
250		}
251		winningUsage := Usage{ID: "uQ", CommitmentID: "c1", Quantity: winnerQty}
252	
253		success, conflict := 0, 0
254		for i, c := range calls {
255			r := results[i]
256			if c.quantity == winnerQty {
257				if r.err != nil || r.usage != winningUsage {
258					t.Fatalf("winner-group call %d = %+v, err %v; want %+v", i, r.usage, r.err, winningUsage)
259				}
260				success++
261			} else {
262				// 落败组即使其数量此刻会超过被首次使用后压缩的余量，也只能得到
263				// 编号冲突，不能报超量使用，更不能扣减。
264				if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
265					t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
266				}
