272		}
273	
274		// 实物与有效占用只随胜出数量变化一次；可承诺数量恒为初始的五件。
275		st, _ := s.PartStatus("part1", nowOK)
276		wantPhys, wantOccupied := 10-winnerQty, 5-winnerQty
277		if st.PhysicalRemaining != wantPhys || st.ActiveOccupied != wantOccupied || st.Committable != 5 {
278			t.Fatalf("winner qty %d: stock = %+v, want phys=%d occupied=%d committable=5",
279				winnerQty, st, wantPhys, wantOccupied)
280		}
281	
282		// 赛后按胜出内容提交取回原记录；按落败内容提交仍冲突，数量不再变化。
283		if got, err := s.Use("uQ", "c1", winnerQty, nowOK.Add(day)); err != nil || got != winningUsage {
284			t.Fatalf("winner content retry = %+v, err %v; want %+v", got, err, winningUsage)
285		}
