48	// assertExcludedInWindow 断言请求在保修期内被故障除外原因拒绝，且直接查询
49	// 与按请求查看的结果一致。
50	func assertExcludedInWindow(t *testing.T, s *Store, requestID string) {
51		t.Helper()
52		e, err := s.Evaluate(requestID, nowOK)
