66		ve := view.Eligibility
67		if ve.Eligible != e.Eligible || ve.Excluded != e.Excluded || len(ve.Reasons) != len(e.Reasons) {
68			t.Fatalf("%s: view %+v disagrees with evaluate %+v", requestID, ve, e)
69		}
70		for i := range e.Reasons {
71			if ve.Reasons[i] != e.Reasons[i] {
72				t.Fatalf("%s: view reasons %v disagree with %v", requestID, ve.Reasons, e.Reasons)
