98	// TestRegistrationSnapshotsCallerList 登记成功后以登记当时的清单为准：
99	// 调用方替换或补入自己持有的原清单，不改变已登记产品的除外规则。
100	func TestRegistrationSnapshotsCallerList(t *testing.T) {
101		t.Run("replace original code", func(t *testing.T) {
102			codes := []string{"BROKEN_SEAL"}
103			s := isolationStore(t, codes)
104			mustSubmit(t, s, "rOrig", "BROKEN_SEAL")
105			mustSubmit(t, s, "rReplaced", "NOISE")
106	
107			// 登记完成后把原清单中的除外代码替换成另一代码。
108			codes[0] = "NOISE"
109			p, err := s.Product("p1")
110			if err != nil {
111				t.Fatalf("product: %v", err)
112			}
113			assertExcludedCodes(t, p, "BROKEN_SEAL")
114			// 原除外代码仍被拒绝；替换进来的代码原本不在清单中，应合格。
115			assertExcludedInWindow(t, s, "rOrig")
116			assertEligibleInWindow(t, s, "rReplaced")
